const error = $input.first().json;

const workflowNombre = error.workflow?.name || 'Desconocido';
const nodoNombre = error.execution?.lastNodeExecuted || 'Desconocido';
const mensajeError = error.execution?.error?.message || JSON.stringify(error).substring(0, 500);
const fecha = new Date().toISOString();

return [{
  json: {
    workflow_nombre: workflowNombre,
    nodo_nombre: nodoNombre,
    mensaje_error: mensajeError,
    fecha: fecha,
    texto_email: `Se ha producido un error en el sistema de liquidaciones.\n\nWorkflow: ${workflowNombre}\nNodo: ${nodoNombre}\nError: ${mensajeError}\nFecha: ${fecha}\n\nRevisa el sistema cuanto antes.`
  }
}];
